  & body .rx-catalog:has(#catalog-search-status:not(:empty)) .rx-results { top: calc(100% + 6px); }
  & body .rx-results[hidden] { display: none; }
  & body .rx-results [role="option"] {
    display: grid; grid-template-columns: 4.6em minmax(0, 1fr) auto; align-items: center; gap: 12px;
