  & body .rx-results .rx-tk { font: 650 13px/1.2 var(--sk-ui); letter-spacing: .02em; font-variant-numeric: tabular-nums; overflow: hidden; text-overflow: ellipsis; }
  & body .rx-results .rx-nm { font: 500 14px/1.3 var(--sk-ui); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  & body .rx-results .rx-st { display: inline-flex; align-items: center; gap: 6px; font: 500 11.5px/1.2 var(--sk-ui); color: var(--muted); white-space: nowrap; }
  & body .rx-results .rx-st::before { content: ""; width: 7px; height: 7px; border-radius: 50%; background: color-mix(in srgb, var(--muted) 45%, transparent); }
  & body .rx-results .rx-st.is-ready::before { background: var(--accent); }
