  & body .rx-tornado-lead { margin: 6px 0 18px !important; font-size: 13.5px !important; color: var(--muted); max-width: 62ch; }
  & body .rx-tornado-rows { display: grid; gap: 4px; }
  & body .rx-tn-row {
    display: grid !important; grid-template-columns: minmax(150px, 34%) 52px minmax(0, 1fr) 52px; grid-template-areas: "label lo plot hi";
    align-items: center; column-gap: 10px; width: 100%; min-height: 0 !important; padding: 9px 10px !important; margin: 0 -10px; box-sizing: content-box;
    background: none !important; border: 0 !important; border-radius: 10px !important; color: var(--ink) !important; text-align: left; cursor: pointer;
    transition: background-color 160ms;
