  & body .rx-tn-label b { font: 600 13.5px/1.3 var(--sk-ui); color: var(--ink); }
  & body .rx-tn-label small { font-size: 11.5px !important; color: var(--muted); font-variant-numeric: tabular-nums; }
  & body .rx-tn-plot { grid-area: plot; position: relative; height: 22px; }
  & body .rx-tn-plot > i { position: absolute; top: 3px; bottom: 3px; left: 0; width: 100%; transform-origin: 0 50%; transition: transform 420ms cubic-bezier(.2, .8, .2, 1); }
  & body .rx-tn-down { transform: translateX(calc(var(--a, 0) * 100%)) scaleX(var(--w, 0)); background: color-mix(in srgb, #c2410c 60%, var(--surface)); border-radius: 3px 0 0 3px; }
  & body .rx-tn-up { transform: translateX(calc(var(--a, 0) * 100%)) scaleX(var(--w, 0)); background: var(--accent); border-radius: 0 3px 3px 0; }
  & body .rx-tn-base { top: -2px !important; bottom: -2px !important; width: 2px !important; margin-left: -1px; transform: translateX(calc(var(--a, 0) * 100cqw)); background: var(--ink); transition: none !important; }
  & body .rx-tn-plot { container-type: inline-size; }
  & body .rx-tn-lo, & body .rx-tn-hi { font: 600 12px/1 var(--sk-ui); font-variant-numeric: tabular-nums; color: var(--muted); }
  & body .rx-tn-lo { grid-area: lo; text-align: right; }
  & body .rx-tn-hi { grid-area: hi; text-align: left; }
  & body .rx-tornado-most { margin: 14px 0 0 !important; padding: 12px 14px; border-radius: 10px; background: color-mix(in srgb, var(--accent) 6%, var(--surface)); font-size: 13px !important; color: var(--ink); }
  @media (min-width: 1100px) {
    & body .guided-screen #guided-pane-result > .rx-tornado { grid-column: 2; grid-row: 2; margin-top: 28px; }
    & body .guided-screen #guided-pane-result > .result-actions { grid-row: 3; }
  }
  @media (max-width: 600px) {
    & body .rx-tn-row { grid-template-columns: 46px minmax(0, 1fr) 46px; grid-template-areas: "label label label" "lo plot hi"; row-gap: 6px; }
  }
  /* Story numbers: how far each one moves the value, as a short bar. */
  & body .rx-story-impact { position: relative; display: block; margin-top: 8px; padding-top: 8px; font-size: 11px; line-height: 1.35; color: var(--muted); }
  & body .rx-story-impact:empty { display: none; }
  & body .rx-story-impact::before {
    content: ""; position: absolute; left: 0; top: 0; width: 100%; height: 3px; border-radius: 3px; transform-origin: 0 50%;
    transform: scaleX(var(--w, 0)); background: color-mix(in srgb, var(--accent) 55%, transparent); transition: transform 420ms cubic-bezier(.2, .8, .2, 1);
  }
  @media (prefers-reduced-motion: reduce) { & body .rx-tn-plot > i, & body .rx-story-impact::before { transition: none !important; } }
}
:root[data-skin="report"] {
  /* Reality check: what the driver implies, in one plain sentence before moving on. */
  & body .rx-check {
    display: flex; gap: 10px; align-items: baseline; margin: 28px 0 0 !important; padding: 14px 16px; border-radius: 12px;
    background: color-mix(in srgb, var(--ink) 4%, var(--surface)); border: 1px solid var(--line);
    font-size: 13.5px !important; line-height: 1.55; color: var(--ink);
