  & body .rx-check > b { flex: none; font: 700 10.5px/1.6 var(--sk-ui); letter-spacing: .07em; text-transform: uppercase; color: var(--accent); }
  & body .rx-check + .rx-next { margin-top: 18px; }
  @media (max-width: 600px) { & body .rx-check { flex-direction: column; gap: 4px; } }
}
