    padding: 3px 10px; border-radius: 999px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
    background: color-mix(in srgb, var(--sk-panel-ink, #fff) 16%, transparent); color: var(--sk-panel-ink, #fff); font: 600 12px/1.4 var(--sk-ui);
